{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "title": "Source-to-output edit map",
  "required": [
    "version",
    "timeline",
    "clips"
  ],
  "properties": {
    "version": {
      "const": "1.0"
    },
    "timeline": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "fps",
        "duration"
      ],
      "properties": {
        "fps": {
          "const": 25
        },
        "duration": {
          "type": "number",
          "minimum": 300,
          "maximum": 360
        }
      }
    },
    "clips": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "clip_id",
          "kind",
          "track",
          "output_range",
          "source",
          "source_range",
          "relationship",
          "speaker_ids"
        ],
        "properties": {
          "clip_id": {
            "type": "string"
          },
          "kind": {
            "enum": [
              "video",
              "audio",
              "title"
            ]
          },
          "track": {
            "type": "string"
          },
          "output_range": {
            "type": "array",
            "items": {
              "type": "number",
              "minimum": 0
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "[start,end] seconds; end must exceed start; output bounds and ordering are semantic checks"
          },
          "source": {
            "type": [
              "string",
              "null"
            ]
          },
          "source_range": {
            "anyOf": [
              {
                "type": "array",
                "items": {
                  "type": "number",
                  "minimum": 0
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[start,end] seconds; end must exceed start; output bounds and ordering are semantic checks"
              },
              {
                "type": "null"
              }
            ]
          },
          "relationship": {
            "enum": [
              "sync",
              "broll",
              "archival",
              "editorial_title"
            ]
          },
          "speaker_ids": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "text": {
            "type": "string"
          },
          "claim_ids": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "notes": {
            "type": "string"
          }
        }
      }
    },
    "notes": {
      "type": "string"
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "title": "Claims in the finished film",
  "required": [
    "claims"
  ],
  "properties": {
    "claims": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "claim_id",
          "text_zh",
          "status",
          "output_range",
          "evidence"
        ],
        "properties": {
          "claim_id": {
            "type": "string"
          },
          "text_zh": {
            "type": "string",
            "minLength": 1
          },
          "status": {
            "enum": [
              "prior_plan",
              "proposal",
              "adopted",
              "rejected",
              "open",
              "correction",
              "personal_view",
              "editorial_interpretation"
            ]
          },
          "output_range": {
            "type": "array",
            "items": {
              "type": "number",
              "minimum": 0
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "[start,end] seconds; end must exceed start; output bounds and ordering are semantic checks"
          },
          "evidence": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "source",
                "source_range"
              ],
              "properties": {
                "source": {
                  "type": "string",
                  "pattern": "^media/"
                },
                "source_range": {
                  "type": "array",
                  "items": {
                    "type": "number",
                    "minimum": 0
                  },
                  "minItems": 2,
                  "maxItems": 2,
                  "description": "[start,end] seconds; end must exceed start; output bounds and ordering are semantic checks"
                },
                "speaker_id": {
                  "type": [
                    "string",
                    "null"
                  ]
                }
              }
            }
          },
          "notes": {
            "type": "string"
          }
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "title": "Stable speaker mapping",
  "required": [
    "speakers"
  ],
  "properties": {
    "speakers": {
      "type": "array",
      "minItems": 4,
      "maxItems": 4,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "speaker_id",
          "display_label",
          "audio_sources",
          "camera_observations",
          "identity_evidence"
        ],
        "properties": {
          "speaker_id": {
            "type": "string"
          },
          "display_label": {
            "type": "string"
          },
          "role": {
            "type": [
              "string",
              "null"
            ]
          },
          "audio_sources": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "string",
              "pattern": "^media/audio/"
            }
          },
          "camera_observations": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "required": [
                "source",
                "source_range",
                "description"
              ],
              "properties": {
                "source": {
                  "type": "string",
                  "pattern": "^media/"
                },
                "source_range": {
                  "type": "array",
                  "items": {
                    "type": "number",
                    "minimum": 0
                  },
                  "minItems": 2,
                  "maxItems": 2,
                  "description": "[start,end] seconds; end must exceed start; output bounds and ordering are semantic checks"
                },
                "description": {
                  "type": "string"
                }
              }
            }
          },
          "identity_evidence": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "source",
                "source_range"
              ],
              "properties": {
                "source": {
                  "type": "string",
                  "pattern": "^media/"
                },
                "source_range": {
                  "type": "array",
                  "items": {
                    "type": "number",
                    "minimum": 0
                  },
                  "minItems": 2,
                  "maxItems": 2,
                  "description": "[start,end] seconds; end must exceed start; output bounds and ordering are semantic checks"
                },
                "speaker_id": {
                  "type": [
                    "string",
                    "null"
                  ]
                }
              }
            }
          }
        }
      }
    }
  }
}

